package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.PlatformTransactionManager;import java.nio.file.*;import java.util.*;import java.util.concurrent.TimeUnit;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true") class LegacyFinanceMailLocalDatabaseTest {
 @Autowired FeatureStore store;@Autowired PlatformTransactionManager manager;LegacyReportMailLocalDatabaseTest f;LegacyFinanceMailService service;LegacyHtmlPdfRenderer renderer;byte[] pdf;final LegacyFinanceMailService.Period period=new LegacyFinanceMailService.Period("2024-02",null,null);
 @BeforeEach void setup()throws Exception{f=new LegacyReportMailLocalDatabaseTest();f.store=store;f.manager=manager;f.setup();f.gate("legacy-finance-mail","{\"enabled\":true,\"writeEnabled\":true,\"sendEnabled\":true,\"reconcileEnabled\":true}");f.gate("legacy-monthly-reports","{\"enabled\":true}");store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2024-02-29 12:00:00' WHERE ListDiagnosisProjectId=?",f.order);renderer=mock(LegacyHtmlPdfRenderer.class);pdf=Files.readAllBytes(f.pdf);when(renderer.render(anyString())).thenReturn(pdf);service=new LegacyFinanceMailService(store,f.access,mock(LegacyOrderDetailService.class),f.transport,manager,(int)f.profile,"","synthetic-finance-key",new LegacyMonthlyReportService(store,f.access,new LegacyReportLinks("https://petlis.invalid/","synthetic-finance-key")),renderer,new LegacyFinanceMailFiles(f.root.toString()));}
 @AfterEach void cleanup()throws Exception{if(f==null)return;store.jdbc().update("DELETE a FROM lin_mail_attempt a JOIN lin_mail_message m ON m.id=a.message_id WHERE m.requested_by=? AND m.business_type='FINANCE_MAIL'",f.actor);store.jdbc().update("DELETE FROM lin_mail_message WHERE requested_by=? AND business_type='FINANCE_MAIL'",f.actor);store.jdbc().update("DELETE FROM lin_audit_record WHERE actor_user_id=? AND resource_type='LEGACY_FINANCE_MAIL'",f.actor);store.jdbc().update("DELETE FROM lin_lb_noticemail WHERE HospId=?",f.hospital);f.cleanup();}
 LegacyFinanceMailService.FinanceCommand command(){return new LegacyFinanceMailService.FinanceCommand(period,f.contact,"财务账单邮件","<p>邮件正文</p>","<p>账单正文 12.50</p>","2024-02原账单",f.key(),service.compose(f.hospital,period).get("editToken").toString());}
 @Test void financeAttachesExactPdfAndWritesOnlyOriginalNoticeOnce()throws Exception{var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order);var c=command();long id=service.queueFinance(f.hospital,c);assertEquals(id,service.queueFinance(f.hospital,c));verify(renderer,times(1)).render("<p>账单正文 12.50</p>");assertEquals("SENT",service.dispatch(id).get("status"));var received=f.sink.received.get(8,TimeUnit.SECONDS);var mime=(jakarta.mail.Multipart)received.getContent();assertEquals(2,mime.getCount());assertEquals("2024-02原账单.pdf",mime.getBodyPart(1).getFileName());try(var input=mime.getBodyPart(1).getInputStream()){assertArrayEquals(pdf,input.readAllBytes());}assertTrue(mime.getBodyPart(0).getContent().toString().contains("邮件正文"));var notice=store.one("SELECT * FROM lin_lb_noticemail WHERE HospId=? AND PayMonth='2024-02'",f.hospital);assertEquals(1,((Number)notice.get("IsSendMail")).intValue());assertEquals("SENT",service.dispatch(id).get("status"));assertEquals(notice,store.one("SELECT * FROM lin_lb_noticemail WHERE IID=?",notice.get("IID")));verify(f.transport,times(1)).send(any(),any(),eq(LegacyMailRoutingRules.Kind.FINANCE));assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order));}
 @Test void unknownAcceptanceReconcilesWithoutSecondSmtp(){long id=service.queueFinance(f.hospital,command());doThrow(new LegacyMailTransport.DeliveryUncertainException()).when(f.transport).send(any(),any(),any());assertEquals("UNKNOWN",service.dispatch(id).get("status"));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_noticemail WHERE HospId=?",Integer.class,f.hospital));var reconcile=new LegacyFinanceMailService.ReconcileCommand("ACCEPTED","Synthetic finance SMTP receipt confirms acceptance",true,false,service.message(id).get("editToken").toString(),f.key());assertEquals("SENT",service.reconcile(id,reconcile).get("status"));assertEquals("SENT",service.reconcile(id,reconcile).get("status"));verify(f.transport,times(1)).send(any(),any(),any());}
 @Test void changedFinancialRowsBlockBeforeAnySmtp(){long id=service.queueFinance(f.hospital,command());store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET TestPrice=33.00 WHERE DiagnosisDetailId=?",f.detail);assertEquals("BLOCKED",service.dispatch(id).get("status"));verify(f.transport,never()).send(any(),any(),any());}
 @Test void alteredAttachmentCannotBeSent()throws Exception{long id=service.queueFinance(f.hospital,command());var row=store.one("SELECT attachments_json FROM lin_mail_message WHERE id=?",id);var path=new com.fasterxml.jackson.databind.ObjectMapper().readTree(row.get("attachments_json").toString()).path("path").asText();Files.writeString(f.root.resolve(path),"%PDF-tampered");assertEquals("BLOCKED",service.dispatch(id).get("status"));verify(f.transport,never()).send(any(),any(),any());}
 @Test void previouslySentNoticePreservesOriginalTimestampsAndRemark()throws Exception{long notice=store.insert("INSERT INTO lin_lb_noticemail(HospId,PayMonth,IsSendMail,Remark,CreateDt,UpdateDt) VALUES(?,'2024-02',1,'keep','2020-01-01','2020-01-02')",f.hospital);var before=store.one("SELECT * FROM lin_lb_noticemail WHERE IID=?",notice);long id=service.queueFinance(f.hospital,command());assertEquals("SENT",service.dispatch(id).get("status"));assertEquals(before,store.one("SELECT * FROM lin_lb_noticemail WHERE IID=?",notice));}
 @Test void acceptedCallbackFailureRecoversWithoutResending(){service=spy(service);doThrow(new BusinessException(409,"synthetic callback failure")).doCallRealMethod().when(service).businessCallback(any());long id=service.queueFinance(f.hospital,command());var first=service.dispatch(id);assertEquals("ACCEPTED",first.get("status"));assertEquals("FAILED",first.get("callback_status"));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_noticemail WHERE HospId=?",Integer.class,f.hospital));assertEquals("SENT",service.dispatch(id).get("status"));verify(f.transport,times(1)).send(any(),any(),any());}
 @Test void unsentNoticeUpdatesOnlyFlagAndUpdateTime()throws Exception{long notice=store.insert("INSERT INTO lin_lb_noticemail(HospId,PayMonth,IsSendMail,Remark,CreateDt,UpdateDt) VALUES(?,'2024-02',0,'keep','2020-01-01','2020-01-02')",f.hospital);var before=store.one("SELECT * FROM lin_lb_noticemail WHERE IID=?",notice);long id=service.queueFinance(f.hospital,command());assertEquals("SENT",service.dispatch(id).get("status"));var after=store.one("SELECT * FROM lin_lb_noticemail WHERE IID=?",notice);assertEquals(1,((Number)after.get("IsSendMail")).intValue());assertEquals(before.get("Remark"),after.get("Remark"));assertEquals(before.get("CreateDt"),after.get("CreateDt"));assertNotEquals(before.get("UpdateDt"),after.get("UpdateDt"));}
 @Test void rangeUsesEmptyOriginalNotificationMonthAndForeignContactCannotQueue(){var range=new LegacyFinanceMailService.Period(null,"2024-02-01T00:00:00","2024-03-01T00:00:00");var c=command();var token=service.compose(f.hospital,range).get("editToken").toString();assertEquals(404,assertThrows(BusinessException.class,()->service.queueFinance(f.hospital,new LegacyFinanceMailService.FinanceCommand(range,Long.MAX_VALUE,c.title(),c.html(),c.reportHtml(),c.pdfTitle(),f.key(),token))).getCode());long id=service.queueFinance(f.hospital,new LegacyFinanceMailService.FinanceCommand(range,c.contactId(),c.title(),c.html(),c.reportHtml(),c.pdfTitle(),f.key(),token));assertEquals("SENT",service.dispatch(id).get("status"));assertEquals(1,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_noticemail WHERE HospId=? AND PayMonth='' AND IsSendMail=1",Integer.class,f.hospital));}

}
